import math
from nearproof import (Prover, Verifier, Challenge, ChallengeStateError,
                       audit_bound_policy, context_digest)

KEY = b"k"*32
ctx = b"c"*32; opn = b"o"*32
dig = context_digest(ctx, opn)

class Clock:
    def __init__(self): self.t = 0.0
    def __call__(self): return self.t

# --- state/TTL first: expired challenge with opening=None / garbage ---
clk = Clock()
p = Prover(KEY); v = Verifier(KEY, clock=clk, replay_protection=True, challenge_ttl_seconds=1.0)
ch = v.new_challenge(context=ctx, digest=dig)
clk.t = 1.0
try:
    v.verify_bound(ch, None, None, opening=None)
except ChallengeStateError as e:
    print("expired+None opening -> ChallengeStateError:", e)

# expired challenge with non-bytes opening and non-finite started
try:
    v.verify_bound(ch, b"x", math.nan, opening=7)
except ChallengeStateError as e:
    print("expired stays terminal:", e)

# failed challenge does not get consumed; clock rollback cannot revive
clk.t = 0.5
try:
    v.verify_bound(ch, p.reveal(ch, ctx, opn), 0.0, opening=opn)
except ChallengeStateError as e:
    print("rollback no revive:", e)

# --- unknown challenge wins over opening=None ---
clk2 = Clock()
v2 = Verifier(KEY, clock=clk2, replay_protection=True)
foreign = Challenge(99, b"n"*16)
try:
    v2.verify_bound(foreign, None, None, opening=None)
except ChallengeStateError as e:
    print("unknown -> ChallengeStateError:", e)

# --- consumed challenge wins over bad opening ---
ch2 = v2.new_challenge(context=ctx, digest=dig)
clk2.t = 0.1
b = v2.verify_bound(ch2, p.reveal(ch2, ctx, opn), 0.0, opening=opn)
try:
    v2.verify_bound(ch2, b"bad", math.nan, opening=b"short")
except ChallengeStateError as e:
    print("consumed -> ChallengeStateError:", e)

# --- audit_bound_policy: boundaries ---
end = b.evidence.end
m0 = audit_bound_policy(b, KEY, now=end, max_age=0.0)
m1 = audit_bound_policy(b, KEY, now=end+10, max_age=10)
print("boundary equal ok:", round(m0.distance_meters, 6), round(m1.distance_meters, 6))
for kw in [dict(now=end-1e-9, max_age=10), dict(now=end+10.0001, max_age=10)]:
    try:
        audit_bound_policy(b, KEY, **kw); print("FAIL no raise")
    except ValueError as e:
        print("rejected:", e)
# now omitted
try: audit_bound_policy(b, KEY, max_age=10)
except ValueError as e: print("now required:", e)
# bool rejected
try: audit_bound_policy(b, KEY, now=True, max_age=10)
except ValueError as e: print("bool now:", e)
try: audit_bound_policy(b, KEY, now=end, max_age=False)
except ValueError as e: print("bool max_age:", e)
# max_age=None: no clock, now ignored
m = audit_bound_policy(b, KEY, now=object(), max_age=None)
print("None policy ignores now, returns Measurement:", type(m).__name__)
# crypto first: tamper record, valid freshness args
import dataclasses
bad = dataclasses.replace(b, opening=b"z"*32)
try: audit_bound_policy(bad, KEY, now=end, max_age=0.0)
except ValueError as e: print("tampered:", e)
# bytes input path
m2 = audit_bound_policy(b.to_bytes(), KEY, now=end, max_age=0.0)
print("bytes path:", m2 == m0)
